CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 REAL UNIQUE, c1 TEXT) STRICT;
INSERT OR IGNORE INTO t0(c0, c1) VALUES(5.043, 'tau');
INSERT OR IGNORE INTO t0(c0, c1) VALUES(-3.738, 'eta');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 VARCHAR(10), c1, c2 REAL DEFAULT 'd', c3 NUMERIC UNIQUE, c4  CHECK(c4 IS NULL OR length(c4) < 40));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(x'', 46.965, -516.8655, NULL, 'Ελλάδα');
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(-173, 'kappa', -4, 2.5, 205);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(610.4912, -1e308, '1e3', x'', x'39837cd975');
SELECT length('café'), upper('café'), lower('café'), substr('café', 3, 3), instr('café', 'phi'), replace('café', '', ''), trim('café'), ltrim('café', 'ab'), hex('café'), quote('café'), unicode('café'), 'café' LIKE 'A%', 'café' GLOB '*', char(88, 864), 'café' || 'phi', 'café' < 'phi', 'café' = 'phi' COLLATE NOCASE;
SELECT length('0x1F'), upper('0x1F'), lower('0x1F'), substr('0x1F', -2, 1), instr('0x1F', 'psi'), replace('0x1F', 'a', 'XY'), trim('0x1F'), ltrim('0x1F', 'ab'), hex('0x1F'), quote('0x1F'), unicode('0x1F'), '0x1F' LIKE 'A%', '0x1F' GLOB '*[a-m]*', char(66, 836), '0x1F' || 'psi', '0x1F' < 'psi', '0x1F' = 'psi' COLLATE NOCASE;
SELECT length('xi'), upper('xi'), lower('xi'), substr('xi', -3, 4), instr('xi', ''), replace('xi', 'é', ''), trim('xi'), ltrim('xi', 'ab'), hex('xi'), quote('xi'), unicode('xi'), 'xi' LIKE '_', 'xi' GLOB '?', char(84, 523), 'xi' || '', 'xi' < '', 'xi' = '' COLLATE NOCASE;
SELECT length('nu'), upper('nu'), lower('nu'), substr('nu', 3, 2), instr('nu', 'omicron'), replace('nu', 'é', ''), trim('nu'), ltrim('nu', 'ab'), hex('nu'), quote('nu'), unicode('nu'), 'nu' LIKE '_', 'nu' GLOB '?', char(84, 437), 'nu' || 'omicron', 'nu' < 'omicron', 'nu' = 'omicron' COLLATE NOCASE;
SELECT length('rho'), upper('rho'), lower('rho'), substr('rho', 3, 4), instr('rho', 'x_y'), replace('rho', 'a', 'XY'), trim('rho'), ltrim('rho', 'ab'), hex('rho'), quote('rho'), unicode('rho'), 'rho' LIKE '%é%', 'rho' GLOB '*', char(90, 997), 'rho' || 'x_y', 'rho' < 'x_y', 'rho' = 'x_y' COLLATE NOCASE;
SELECT length('sigma'), upper('sigma'), lower('sigma'), substr('sigma', 1, 3), instr('sigma', 'a%b'), replace('sigma', 'a', ''), trim('sigma'), ltrim('sigma', 'ab'), hex('sigma'), quote('sigma'), unicode('sigma'), 'sigma' LIKE 'A%', 'sigma' GLOB '*[a-m]*', char(80, 553), 'sigma' || 'a%b', 'sigma' < 'a%b', 'sigma' = 'a%b' COLLATE NOCASE;
SELECT id, (SELECT count(*) FROM t1 WHERE t1.id <= t0.id) FROM t0 ORDER BY c0, id;
SELECT id FROM t0 WHERE id NOT IN (SELECT id FROM t1) ORDER BY id;
SELECT id FROM t0 x WHERE EXISTS (SELECT 1 FROM t1 y WHERE y.id = x.id + 1) ORDER BY id;
SELECT c0 FROM t0 INTERSECT SELECT id FROM t1 ORDER BY 1 LIMIT 14 OFFSET 3;
SELECT json_valid('{"a":}'), json('{"a":}'), json_type('{"a":}'), json_array_length('{"a":}'), json_extract('{"a":}', '$.a', '$[1]', '$.b[2].c'), '{"a":}' -> '$.b', '{"a":}' ->> '$.n.m.o';
SELECT key, value, type FROM json_each('{"a":}') ORDER BY key;
SELECT json_set('{"a":}', '$.z', 1), json_insert('{"a":}', '$.a', 2), json_remove('{"a":}', '$.a'), json_patch('{"a":1}', '{"b":2}');
SELECT json_group_array(id), json_group_object(CAST(id AS TEXT), c1) FROM t1;
SELECT json_object('id', id, 'v', c2) FROM t1 ORDER BY id LIMIT 4;
